class Solution {
public:
    vector<string> invalidTransactions(vector<string>& transactions) {
        struct Tx {
            string name;
            int time;
            int amount;
            string city;
            int id;
        };
        int n = transactions.size();
        vector<Tx> txs;
        unordered_map<string, vector<int>> name_map;

        for (int i = 0; i < n; ++i) {
            stringstream ss(transactions[i]);
            string name, time_str, amount_str, city;
            getline(ss, name, ',');
            getline(ss, time_str, ',');
            getline(ss, amount_str, ',');
            getline(ss, city, ',');
            txs.push_back({name, stoi(time_str), stoi(amount_str), city, i});
            name_map[name].push_back(i);
        }

        vector<bool> invalid(n, false);
        for (int i = 0; i < n; ++i) {
            if (txs[i].amount > 1000) invalid[i] = true;
            for (int j : name_map[txs[i].name]) {
                if (i != j && txs[i].city != txs[j].city && abs(txs[i].time - txs[j].time) <= 60) {
                    invalid[i] = true;
                    invalid[j] = true;
                }
            }
        }

        vector<string> res;
        for (int i = 0; i < n; ++i) {
            if (invalid[i]) res.push_back(transactions[i]);
        }
        return res;
    }
};

import java.util.*;

class Solution {
    static class Tx {
        String name;
        int time;
        int amount;
        String city;
        int id;
        Tx(String name, int time, int amount, String city, int id) {
            this.name = name;
            this.time = time;
            this.amount = amount;
            this.city = city;
            this.id = id;
        }
    }

    public List<String> invalidTransactions(String[] transactions) {
        int n = transactions.length;
        Tx[] txs = new Tx[n];
        Map<String, List<Integer>> nameMap = new HashMap<>();

        for (int i = 0; i < n; i++) {
            String[] parts = transactions[i].split(",");
            txs[i] = new Tx(parts[0], Integer.parseInt(parts[1]), Integer.parseInt(parts[2]), parts[3], i);
            nameMap.computeIfAbsent(parts[0], k -> new ArrayList<>()).add(i);
        }

        boolean[] invalid = new boolean[n];
        for (int i = 0; i < n; i++) {
            if (txs[i].amount > 1000) invalid[i] = true;
            for (int j : nameMap.get(txs[i].name)) {
                if (i != j && !txs[i].city.equals(txs[j].city) && Math.abs(txs[i].time - txs[j].time) <= 60) {
                    invalid[i] = true;
                    invalid[j] = true;
                }
            }
        }

        List<String> res = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (invalid[i]) res.add(transactions[i]);
        }
        return res;
    }
}

var invalidTransactions = function(transactions) {
    const n = transactions.length;
    const txs = [];
    const nameMap = new Map();

    for (let i = 0; i < n; i++) {
        const [name, timeStr, amountStr, city] = transactions[i].split(',');
        txs.push({ name, time: Number(timeStr), amount: Number(amountStr), city, id: i });
        if (!nameMap.has(name)) nameMap.set(name, []);
        nameMap.get(name).push(i);
    }

    const invalid = new Set();
    for (let i = 0; i < n; i++) {
        if (txs[i].amount > 1000) invalid.add(i);
        for (const j of nameMap.get(txs[i].name)) {
            if (i !== j && txs[i].city !== txs[j].city && Math.abs(txs[i].time - txs[j].time) <= 60) {
                invalid.add(i);
                invalid.add(j);
            }
        }
    }

    const res = [];
    for (let i = 0; i < n; i++) {
        if (invalid.has(i)) res.push(transactions[i]);
    }
    return res;
};
